schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/activation-metrics.json",
  "title": "Activation Metrics report",
  "type": "object",
  "required": ["activation_event", "window_days", "period_start", "period_end", "data_cutoff", "signups_total", "sample_floor", "channel_attribution", "metrics", "time_to_activation", "funnel", "findings"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "snake": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "rate": {"type": "number", "minimum": 0, "maximum": 1},
    "period": {
      "type": "object",
      "required": ["start", "end"],
      "additionalProperties": false,
      "properties": {"start": {"$ref": "#/definitions/date"}, "end": {"$ref": "#/definitions/date"}}
    },
    "group": {
      "type": "object",
      "required": ["users", "d30_retention"],
      "additionalProperties": false,
      "properties": {"users": {"type": "integer", "minimum": 1}, "d30_retention": {"$ref": "#/definitions/rate"}}
    }
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "activation_event": {"$ref": "#/definitions/snake"},
    "window_days": {"type": "integer", "minimum": 1},
    "period_start": {"$ref": "#/definitions/date"},
    "period_end": {"$ref": "#/definitions/date"},
    "data_cutoff": {"$ref": "#/definitions/date"},
    "previous_period": {"$ref": "#/definitions/period"},
    "signups_total": {"type": "integer", "minimum": 1},
    "sample_floor": {"type": "integer", "minimum": 1},
    "channel_attribution": {"type": "boolean"},
    "metrics": {
      "type": "array",
      "minItems": 1,
      "contains": {"properties": {"name": {"const": "activation_rate"}}, "required": ["numerator", "denominator"]},
      "items": {
        "type": "object",
        "required": ["name", "value", "unit"],
        "additionalProperties": false,
        "properties": {
          "name": {"$ref": "#/definitions/snake"},
          "value": {"type": "number"},
          "unit": {"type": "string", "enum": ["ratio", "count", "days", "hours", "pp"]},
          "numerator": {"type": "integer", "minimum": 0},
          "denominator": {"type": "integer", "minimum": 1},
          "low_sample": {"type": "boolean"}
        },
        "if": {"properties": {"unit": {"const": "ratio"}}},
        "then": {"properties": {"value": {"$ref": "#/definitions/rate"}}}
      }
    },
    "time_to_activation": {
      "type": "object",
      "required": ["unit", "median"],
      "anyOf": [{"required": ["p75"]}, {"required": ["p90"]}],
      "additionalProperties": false,
      "properties": {
        "unit": {"type": "string", "enum": ["hours", "days"]},
        "median": {"type": "number", "minimum": 0},
        "p75": {"type": "number", "minimum": 0},
        "p90": {"type": "number", "minimum": 0},
        "mean": {"type": "number", "minimum": 0}
      }
    },
    "d30_lift": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["event", "cohort_signup_start", "cohort_signup_end", "performed", "not_performed", "wording"],
        "additionalProperties": false,
        "properties": {
          "event": {"$ref": "#/definitions/snake"},
          "cohort_signup_start": {"$ref": "#/definitions/date"},
          "cohort_signup_end": {"$ref": "#/definitions/date"},
          "performed": {"$ref": "#/definitions/group"},
          "not_performed": {"$ref": "#/definitions/group"},
          "wording": {"const": "correlation"}
        }
      }
    },
    "funnel": {
      "type": "array",
      "minItems": 2,
      "items": {
        "type": "object",
        "required": ["name", "status"],
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "status": {"type": "string", "enum": ["instrumented", "uninstrumented"]}
        },
        "if": {"properties": {"status": {"const": "instrumented"}}},
        "then": {
          "required": ["event", "entering", "completing", "absolute_drop", "relative_drop"],
          "additionalProperties": false,
          "properties": {
            "name": {"type": "string"},
            "status": {"const": "instrumented"},
            "event": {"$ref": "#/definitions/snake"},
            "entering": {"type": "integer", "minimum": 0},
            "completing": {"type": "integer", "minimum": 0},
            "absolute_drop": {"type": "integer", "minimum": 0},
            "relative_drop": {"$ref": "#/definitions/rate"}
          }
        },
        "else": {
          "required": ["instrumentation_task"],
          "additionalProperties": false,
          "properties": {
            "name": {"type": "string"},
            "status": {"const": "uninstrumented"},
            "instrumentation_task": {"type": "string", "minLength": 8}
          }
        }
      }
    },
    "findings": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["metric", "text", "compared_to", "causal"],
        "additionalProperties": false,
        "properties": {
          "metric": {"$ref": "#/definitions/snake"},
          "text": {"type": "string", "minLength": 20},
          "compared_to": {"$ref": "#/definitions/period"},
          "causal": {"type": "boolean"},
          "product_change": {
            "type": "object",
            "required": ["name", "released_at"],
            "additionalProperties": false,
            "properties": {
              "name": {"type": "string", "minLength": 3},
              "released_at": {"$ref": "#/definitions/date"},
              "ab_test_result": {"type": "string", "minLength": 10}
            }
          }
        },
        "if": {"properties": {"causal": {"const": true}}},
        "then": {"required": ["product_change"], "properties": {"product_change": {"required": ["ab_test_result"]}}}
      }
    }
  }
}

output-contract.example:
{
  "activation_event": "project_created",
  "window_days": 7,
  "period_start": "2026-04-06",
  "period_end": "2026-05-03",
  "data_cutoff": "2026-05-04",
  "signups_total": 7036,
  "sample_floor": 100,
  "channel_attribution": true,
  "metrics": [
    {"name": "activation_rate", "value": 31, "unit": "percent", "numerator": 1482, "denominator": 4780},
    {"name": "activation_rate__referral", "value": 0.23, "unit": "ratio", "numerator": 14, "denominator": 61}
  ],
  "time_to_activation": {"unit": "days", "mean": 6.4},
  "d30_lift": [
    {"event": "invite_sent", "cohort_signup_start": "2026-04-20", "cohort_signup_end": "2026-04-26", "performed": {"users": 120, "d30_retention": 0.51}, "not_performed": {"users": 1568, "d30_retention": 0.17}, "wording": "correlation"}
  ],
  "funnel": [
    {"name": "signup", "status": "instrumented", "event": "signup_completed", "entering": 7036, "completing": 7036, "absolute_drop": 0, "relative_drop": 0},
    {"name": "template picked", "status": "uninstrumented", "instrumentation_task": "GROW-118: emit template_picked", "entering": 4780, "completing": 3200},
    {"name": "project created", "status": "instrumented", "event": "project_created", "entering": 3200, "completing": 1482, "absolute_drop": 1600, "relative_drop": 0.5}
  ],
  "findings": [
    {"metric": "activation_rate", "text": "Activation improved thanks to the new onboarding checklist.", "compared_to": {"start": "2026-03-16", "end": "2026-04-05"}, "causal": true, "product_change": {"name": "onboarding checklist v2", "released_at": "2026-04-13"}}
  ]
}
